-- Fixture QA eksklusif, tidak digunakan pada XAMPP/data nyata.
CREATE TABLE tp (id BIGINT UNSIGNED NOT NULL PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE progres_tp (
 id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 tp_id BIGINT UNSIGNED NOT NULL
) ENGINE=InnoDB;
CREATE TABLE materi (
 id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 tp_id BIGINT UNSIGNED NOT NULL
) ENGINE=InnoDB;
CREATE TABLE progres_materi (
 id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 materi_id BIGINT UNSIGNED NOT NULL
) ENGINE=InnoDB;
CREATE TABLE resume_materi (
 id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 materi_id BIGINT UNSIGNED NOT NULL
) ENGINE=InnoDB;
CREATE TABLE tugas_hots_materi (
 id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 materi_id BIGINT UNSIGNED NOT NULL
) ENGINE=InnoDB;
